import{z as n,x as s,o as B,c as d,q as t,j as o,D as A,d as a,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"端云协同","description":"","frontmatter":{"title":"端云协同","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-cloud-collaboration.md","filePath":"llm/edge-cloud-collaboration.md","lastUpdated":1791063341000}'),D={name:"llm/edge-cloud-collaboration.md"};function p(m,E,F,C,u,h){const l=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="端云协同" tabindex="-1">端云协同 <a class="header-anchor" href="#端云协同" aria-label="Permalink to &quot;端云协同&quot;">​</a></h1><div class="epigraph"><p>端云协同的难点不是把计算切开，是决定「谁来决定」：路由器要有证据、有兜底，还能被追问为什么。</p><footer>—— 据 Kang et al., Neurosurgeon, ASPLOS 2017 与端侧路由产品实践整理</footer></div><p><a href="/llm/edge-energy-budget">上一课</a>把端侧的可持续功率与焦耳每 token 记成了账。主干课<a href="/llm/edge-cloud-split">端云协同</a>已经把切点分了类——阶段、层、草稿/目标——并算清了 KV 下发的体积账。本课不重写切点，写生产系统的另一半：一个请求怎么路由到端或云、路由错了怎么升级与降级、端云两套模型怎么保持一套行为。前几课给了预算，本课让预算变成决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>切点回答「一段计算放哪」，生产系统还要答三问。一问证据：凭什么判断这个请求该端侧扛——设备档位是静态的，电量、温度、内存水位、网络 RTT 是动态的，请求复杂度又是另一个维度；信号不分优先级，规则就调不出来。二问纠错：端上跑到一半扛不住，把请求升级到云，上下文怎么带走、已经流出去的半截回复怎么算——<a href="/llm/stop-sequences">停用词与 stop sequences</a> 的 finish_reason 语义在这里复用：升级要给客户端一个显式的中断原因，不能静默换模型续写。三问一致：端上 4-bit 小模型与云端大模型同场服务，语气、拒答边界、工具协议若有版本差，用户立刻觉得「换了个人」。</p><h3 id="路由器的设计" tabindex="-1">路由器的设计 <a class="header-anchor" href="#路由器的设计" aria-label="Permalink to &quot;路由器的设计&quot;">​</a></h3><p>路由器三层：静态规则打底（设备档位、功能开关、模型清单）；动态信号修正（电量、温度、内存水位、RTT 探测）；复杂度估计选档（短分类器或规则，把长上下文、多约束、工具重的请求直接派云）。每个决策打点：请求特征、信号快照、选择结果，出问题能回放归因。<span class="marginnote">三层可以类比机场分流：静态规则是「按舱位定柜台」——设备档位、功能开关，装机时就定好；动态信号是「看实时人流开通道」——电量、温度、RTT 随时变；复杂度估计是「看行李多大决定走哪」——长上下文、工具重的请求直接派云。三层各管一层变化，混在一起写就调不出来了。</span></p>',7)),(B(),o(i,null,{default:A(()=>[r(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20S%5B%22%E4%BF%A1%E5%8F%B7%E5%BF%AB%E7%85%A7%3A%20%E8%AE%BE%E5%A4%87%20%E7%94%B5%E9%87%8F%20%E6%B8%A9%E5%BA%A6%20RTT%22%5D%0A%20%20S%20--%3E%20E%7B%22%E5%A4%8D%E6%9D%82%E5%BA%A6%E4%BC%B0%E8%AE%A1%22%7D%0A%20%20E%20--%3E%7C%E9%87%8D%7C%20CLOUD%5B%22%E8%B7%AF%E7%94%B1%E4%BA%91%E7%AB%AF%22%5D%0A%20%20E%20--%3E%7C%E8%BD%BB%7C%20EDGE%7B%22%E7%AB%AF%E4%BE%A7%E9%A2%84%E7%AE%97%E5%A4%9F%3F%22%7D%0A%20%20EDGE%20--%3E%7C%E6%98%AF%7C%20LOCAL%5B%22%E7%AB%AF%E4%BE%A7%E6%8E%A8%E7%90%86%22%5D%0A%20%20EDGE%20--%3E%7C%E5%90%A6%7C%20ESC%5B%22%E5%8D%87%E7%BA%A7%E4%BA%91%E7%AB%AF%3A%20%E5%B8%A6%E5%8E%86%E5%8F%B2%E9%87%8D%E6%94%BE%22%5D%0A%20%20LOCAL%20--%3E%20FAIL%5B%22%E4%B8%AD%E9%80%94%E6%89%9B%E4%B8%8D%E4%BD%8F%22%5D%0A%20%20FAIL%20--%3E%20ESC%0A%20%20CLOUD%20--%3E%20DOWN%5B%22%E4%BA%91%E4%B8%8D%E5%8F%AF%E7%94%A8%3A%20%E7%AB%AF%E5%B0%8F%E6%A8%A1%E5%9E%8B%E5%85%9C%E5%BA%95%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"方法",tabindex:"-1"},[a("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("升级路径选「带历史重放」而不是「同步 KV」：KV 体积随上下文线性涨，而且把完整 KV 下发云端等于把原文交出去（隐私账下一课算）；重发的代价只是云上重跑 prefill，云的算力正富余，可靠且泄漏面小。回复流中途升级时，已生成的文本以显式中断原因收尾，衔接由客户端层做，模型层不假装没断过。降级是镜像操作：云不可用或超时，端上小模型顶上，产品层声明能力降级——「现在答得差」比「假装答得好」便宜。草稿/目标协同是精细化的一条：端侧小模型给云上目标打草稿，省的是往返次数，接受率口径见"),e("a",{href:"/llm/on-device-speculative"},"端侧投机解码"),a("。")],-1)),E[5]||(E[5]=e("p",null,"升级时上下文怎么带走，两条路的代价差一个量级：",-1)),(B(),o(i,null,{default:A(()=>[r(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20ESC%5B%22%E7%AB%AF%E4%B8%8A%E6%89%9B%E4%B8%8D%E4%BD%8F%EF%BC%9A%E8%AF%B7%E6%B1%82%E5%8D%87%E7%BA%A7%E5%88%B0%E4%BA%91%22%5D%20--%3E%20Q%7B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E6%80%8E%E4%B9%88%E5%B8%A6%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%8C%E6%AD%A5%20KV%22%7C%20A%5B%22%E4%B8%8B%E4%BC%A0%E5%AE%8C%E6%95%B4%20KV%20cache%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E4%BD%93%E7%A7%AF%E9%9A%8F%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BA%BF%E6%80%A7%E6%B6%A8%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E7%AD%89%E4%BA%8E%E4%BA%A4%E5%87%BA%E5%8E%9F%E6%96%87%EF%BC%9A%E6%B3%84%E6%BC%8F%E9%9D%A2%E5%A4%A7%22%5D%0A%20%20Q%20--%3E%7C%22%E5%B8%A6%E5%8E%86%E5%8F%B2%E9%87%8D%E6%94%BE%22%7C%20B%5B%22%E9%87%8D%E5%8F%91%E5%AF%B9%E8%AF%9D%E8%AE%B0%E5%BD%95%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BA%91%E4%BE%A7%E9%87%8D%E8%B7%91%20prefill%EF%BC%9A%E7%AE%97%E5%8A%9B%E5%AF%8C%E4%BD%99%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E6%B3%84%E6%BC%8F%E9%9D%A2%E5%B0%8F%EF%BC%8C%E9%93%BE%E8%B7%AF%E7%AE%80%E5%8D%95%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">初学者容易把中途升级想成「无缝续写」：换个模型接着往下生成就行。实际上两个模型的输出分布不同，静默续写会出现语气断裂、自相矛盾甚至重复已说过的话；正确做法是用显式中断原因收尾、把衔接交给客户端层——宁可让用户知道「换了个人在答」，也不假装没断过。</span></p><p><span class="marginnote">蜂窝网络 RTT 中位数在几十毫秒、尾部数百毫秒：「每生成一个 token 往返一次云」要从架构选项里划掉，这是端云协同的第一条铁律——可选择的只有批量往返或不往返。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性的机理是把端云差异当配置问题而非模型问题：系统提示、工具协议、安全策略、分词器版本在端云两侧由同一份配置下发，并与模型版本绑定，更新同步走。做不到对齐的能力差异，在路由层显式声明——哪些功能只在云可用，让产品层兜住，而不是让用户自己撞上。<span class="marginnote">这步做错用户立刻能感知：「刚才还挺耐心，突然变冷淡了」——4-bit 小模型和云端大模型挂的系统提示或安全策略版本不一致时就是这样。把配置与模型版本绑定、两侧同步下发，是让端和云「像同一个产品」成本最低的手段；靠各端自己维护副本，迟早漂移。</span>回放的机理同审计：路由是信号与规则的游戏，必然有错分；错分不可归因就无法改进，所以决策日志的 schema 要与模型清单一起版本化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>切点的性能模型与 KV 下发的体积账在主干课已算清，本课不再推导；隐私分级怎么进路由是下一课；草稿接受率的理论在投机课。路由规则不要做成黑盒模型：可解释、可回放、可一键回退到静态规则，是它作为「决策者」的资格线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路由三层：静态规则、动态信号、复杂度选档；每个决策打点可回放。</li><li>升级带历史重放优于同步 KV：体积小、泄漏面小、云算力富余。</li><li>中途升级给显式中断原因，模型层不假装连续。</li><li>端云行为一致靠配置与版本绑定；能力差异在路由层显式声明。</li><li>出处：Kang et al., Neurosurgeon, ASPLOS 2017；Patel et al., Splitwise 的阶段拆分口径；按本课程工程实践整理。</li></ul>',8))])}const T=n(D,[["render",p]]);export{f as __pageData,T as default};
